import sqlite3

conn = sqlite3.connect(":memory:")
conn.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT)")


class User:
    def __init__(self, name, email, id=None):
        self.id = id
        self.name = name
        self.email = email

    def save(self):
        cur = conn.execute(
            "INSERT INTO users (name, email) VALUES (?, ?)", (self.name, self.email)
        )
        self.id = cur.lastrowid
        return self

    @classmethod
    def find_by_id(cls, user_id):
        row = conn.execute(
            "SELECT id, name, email FROM users WHERE id = ?", (user_id,)
        ).fetchone()
        if row is None:
            return None
        return cls(id=row[0], name=row[1], email=row[2])

    def __repr__(self):
        return f"User(id={self.id}, name={self.name!r}, email={self.email!r})"


alice = User("Alice", "alice@example.com").save()
bob = User("Bob", "bob@example.com").save()

print(alice)
print(bob)
print(User.find_by_id(1))
print(User.find_by_id(99))
